export const getPersonLearningEvidenceResponseEvidenceItemTwoEventsItemSeqMin = 0;

export const getPersonLearningEvidenceResponseEvidenceMax = 100;

export const GetPersonLearningEvidenceResponse = zod.object({
  evidence: zod
    .array(
      zod
        .union([
          zod.object({
            kind: zod.literal("conversation"),
            threadId: zod
              .string()
              .describe("Intelligence's id for the conversation."),
            threadName: zod.string().nullable(),
            threadPresent: zod
              .boolean()
              .describe("False when the conversation is gone."),
            unavailable: zod
              .union([
                zod.literal("snapshot-missing"),
                zod.literal("snapshot-unreadable"),
                zod.literal(null),
              ])
              .nullable()
              .describe("Why what was cited can't be read, if it can't."),
            messageCount: zod
              .int()
              .min(
                getPersonLearningEvidenceResponseEvidenceItemOneMessageCountMin,
              ),
            cited: zod.array(
              zod.object({
                id: zod.string(),
                role: zod.enum(["user", "assistant", "tool"]),
                content: zod.string(),
              }),
            ),
          }),
          zod.object({
            kind: zod.literal("recording"),
            trajectoryId: zod
              .string()
              .describe("Intelligence's id for the recording."),
            trajectoryPresent: zod
              .boolean()
              .describe("False when the recording is gone."),
            unavailable: zod
              .union([
                zod.literal("snapshot-missing"),
                zod.literal("snapshot-unreadable"),
                zod.literal(null),
              ])
              .nullable(),
            eventCount: zod
              .int()
              .min(
                getPersonLearningEvidenceResponseEvidenceItemTwoEventCountMin,
              ),
            events: zod
              .array(
                zod.object({
                  seq: zod
                    .int()
                    .min(
                      getPersonLearningEvidenceResponseEvidenceItemTwoEventsItemSeqMin,
                    ),
                  name: zod.string(),
                  offsetMs: zod.number(),
                }),
              )
              .describe("The cited events, in order."),
          }),
        ])
        .describe(
          "One piece of what an insight was learned from: messages cited from a conversation, or events from a recording.",
        ),
    )
    .max(getPersonLearningEvidenceResponseEvidenceMax),
});

